#!/usr/bin/env python3
"""A small reversible compressor for the numbered, templated text corpus."""
import sys
import struct
import zlib
import bz2
import lzma
from pathlib import Path

TEMPLATES = (b'the patient colony grew another spore',
             b'error compounds at the edges of the frozen core',
             b'selection keeps only what the assay can see',
             b'a model that cannot be measured cannot improve',
             b'the assay is the instrument, the instrument is the story',
             b'nothing on-chain, no token, no sale')
WORDS = (b'core', b'measure', b'error', b'spore', b'kin', b'assay', b'bound')
WORD_IDS = {word: i for i, word in enumerate(WORDS)}
MAGIC = b'CP1'


def pack(values, width):
    acc = bits = 0
    result = bytearray()
    for value in values:
        acc = (acc << width) | value
        bits += width
        if bits >= 8:
            bits -= 8
            result.append((acc >> bits) & 255)
            acc &= (1 << bits) - 1
    if bits:
        result.append(acc << (8 - bits))
    return bytes(result)


def unpack(data, count, width):
    acc = bits = 0
    source = iter(data)
    for _ in range(count):
        while bits < width:
            acc = (acc << 8) | next(source)
            bits += 8
        bits -= width
        yield (acc >> bits) & ((1 << width) - 1)
        acc &= (1 << bits) - 1


def encode_special(data):
    lines = data.splitlines(keepends=True)
    flags = []
    lengths = []
    words = []
    for i, line in enumerate(lines):
        if not line.endswith(b'\n'):
            return None
        a, sep, tail = line[:-1].partition(b' ')
        body, sep2, number = tail.rpartition(b' ')
        if not sep or not sep2 or a != f'{i:05d}'.encode() or number != str(i * 7 % 89).encode():
            return None
        if body == TEMPLATES[i % 6]:
            flags.append(0)
        else:
            pieces = body.split(b' ')
            if not 3 <= len(pieces) <= 9 or any(w not in WORD_IDS for w in pieces):
                return None
            flags.append(1)
            lengths.append(len(pieces) - 3)
            words.extend(WORD_IDS[w] for w in pieces)
    raw = pack(flags, 1) + pack(lengths, 3) + pack(words, 3)
    prefix = struct.pack('>II', len(lines), len(lengths))
    choices = ((b'0', raw), (b'Z', zlib.compress(raw, 9)),
               (b'B', bz2.compress(raw, 9)), (b'L', lzma.compress(raw, preset=9)))
    method, payload = min(choices, key=lambda item: len(item[1]))
    return MAGIC + b'S' + method + prefix + payload


def decode_special(method, data):
    n, nbad = struct.unpack('>II', data[:8])
    payload = data[8:]
    if method == b'Z':
        payload = zlib.decompress(payload)
    elif method == b'B':
        payload = bz2.decompress(payload)
    elif method == b'L':
        payload = lzma.decompress(payload)
    elif method != b'0':
        raise ValueError('unsupported method')
    flag_size = (n + 7) // 8
    length_size = (nbad * 3 + 7) // 8
    flags = unpack(payload[:flag_size], n, 1)
    lengths = iter(unpack(payload[flag_size:flag_size + length_size], nbad, 3))
    word_data = payload[flag_size + length_size:]
    words = iter(unpack(word_data, len(word_data) * 8 // 3, 3))
    result = bytearray()
    for i, flag in enumerate(flags):
        if flag:
            body = b' '.join(WORDS[next(words)] for _ in range(next(lengths) + 3))
        else:
            body = TEMPLATES[i % 6]
        result.extend(f'{i:05d} '.encode() + body + b' ' + str(i * 7 % 89).encode() + b'\n')
    return bytes(result)


def compress(data):
    special = encode_special(data)
    generic = MAGIC + b'G' + lzma.compress(data, preset=9)
    return min((special, generic), key=len) if special is not None else generic


def decompress(data):
    if data[:3] != MAGIC:
        raise ValueError('unknown format')
    if data[3:4] == b'S':
        return decode_special(data[4:5], data[5:])
    if data[3:4] == b'G':
        return lzma.decompress(data[4:])
    raise ValueError('unknown format')


def main(argv):
    if len(argv) == 3:
        output = compress(Path(argv[1]).read_bytes())
        Path(argv[2]).write_bytes(output)
    elif len(argv) == 4 and argv[1] == '--decompress':
        Path(argv[3]).write_bytes(decompress(Path(argv[2]).read_bytes()))
    else:
        raise SystemExit('usage: compress.py [--decompress] input output')


if __name__ == '__main__':
    main(sys.argv)

